/** Select the coeff_token table for a given nC (clause 9.2.1). */
export function coeffTokenTableIndex(nC: number): number {
  if (nC === -1) return 4; // chroma DC, 4:2:0
  if (nC === -2) return 5; // chroma DC, 4:2:2
  if (nC < 2) return 0;
  if (nC < 4) return 1;
  if (nC < 8) return 2;
  return 3;
}

